class Gradebook:
    def __init__(self):
        self.students = set()
        self.assignments = {}
        self.scores = {}
    
    def add_student(self, name):
        if name in self.students:
            raise ValueError("Student already exists")
        self.students.add(name)
    
    def add_assignment(self, name, max_points):
        if name in self.assignments:
            raise ValueError("Assignment already exists")
        if not isinstance(max_points, (int, float)) or max_points <= 0:
            raise ValueError("Max points must be a positive number")
        self.assignments[name] = max_points
    
    def record(self, student, assignment, points):
        if student not in self.students:
            raise KeyError("Unknown student")
        if assignment not in self.assignments:
            raise KeyError("Unknown assignment")
        if not isinstance(points, (int, float)) or points < 0 or points > self.assignments[assignment]:
            raise ValueError("Points must be between 0 and max points")
        if student not in self.scores:
            self.scores[student] = {}
        self.scores[student][assignment] = points
    
    def score(self, student, assignment):
        if student not in self.students or assignment not in self.assignments:
            return None
        if student not in self.scores or assignment not in self.scores[student]:
            return None
        return self.scores[student][assignment]

if __name__ == "__main__":
    # Test the Gradebook functionality
    g = Gradebook()
    
    # Test add_student
    g.add_student("Alice")
    g.add_student("Bob")
    
    # Test adding duplicate student
    try:
        g.add_student("Alice")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    # Test add_assignment
    g.add_assignment("Homework 1", 100)
    g.add_assignment("Exam 1", 200)
    
    # Test adding duplicate assignment
    try:
        g.add_assignment("Homework 1", 100)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    # Test adding assignment with invalid max_points
    try:
        g.add_assignment("Quiz 1", -10)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    try:
        g.add_assignment("Quiz 2", 0)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    # Test record
    g.record("Alice", "Homework 1", 85)
    g.record("Bob", "Homework 1", 92)
    g.record("Alice", "Exam 1", 180)
    
    # Test recording with invalid points
    try:
        g.record("Alice", "Homework 1", 150)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    try:
        g.record("Alice", "Homework 1", -10)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    # Test recording with unknown student
    try:
        g.record("Charlie", "Homework 1", 85)
        assert False, "Should have raised KeyError"
    except KeyError:
        pass  # Expected
    
    # Test recording with unknown assignment
    try:
        g.record("Alice", "Quiz 1", 85)
        assert False, "Should have raised KeyError"
    except KeyError:
        pass  # Expected
    
    # Test score method
    assert g.score("Alice", "Homework 1") == 85
    assert g.score("Bob", "Homework 1") == 92
    assert g.score("Alice", "Exam 1") == 180
    assert g.score("Alice", "Quiz 1") is None  # Unknown assignment
    assert g.score("Charlie", "Homework 1") is None  # Unknown student
    
    # Test recording again replaces score
    g.record("Alice", "Homework 1", 95)
    assert g.score("Alice", "Homework 1") == 95
    
    print("All tests passed!")

