        g.add_assignment("Homework 1", 100)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    # Test adding assignment with invalid max_points
    try:
        g.add_assignment("Quiz 1", -10)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    try:
        g.add_assignment("Quiz 2", 0)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    # Test record
    g.record("Alice", "Homework 1", 85)
    g.record("Bob", "Homework 1", 92)
    g.record("Alice", "Exam 1", 180)
    
    # Test recording with invalid points
    try:
        g.record("Alice", "Homework 1", 150)
        assert False, "Should have raised ValueError"
    except ValueError:
