  } catch (e) {
    console.assert(e.message === "Matrix shapes must match for subtraction", "Should throw correct error for subtraction shape mismatch");
  }
  
  // Test non-Matrix operand error
  try {
    m1.add("not a matrix");
    console.assert(false, "Should have thrown error for non-Matrix operand in addition");
  } catch (e) {
    console.assert(e.message === "Operand must be a Matrix", "Should throw correct error for non-Matrix operand in addition");
  }
  
  try {
    m1.sub("not a matrix");
    console.assert(false, "Should have thrown error for non-Matrix operand in subtraction");
  } catch (e) {
    console.assert(e.message === "Operand must be a Matrix", "Should throw correct error for non-Matrix operand in subtraction");
  }
  
  console.log("Add and sub tests passed!");
}

// Add transpose method
Matrix.prototype.transpose = function() {
  const transposedRows = [];
  for (let i = 0; i < this.rows[0].length; i++) {
    const row = [];
    for (let j = 0; j < this.rows.length; j++) {
      row.push(this.rows[j][i]);
    }
    transposedRows.push(row);
  }
  return new Matrix(transposedRows);
};

// Add identity static method
Matrix.identity = function(n) {
  if (typeof n !== 'number' || n <= 0 || !Number.isInteger(n)) {
    throw new Error("n must be a positive integer");
  }
  
  const rows = [];
  for (let i = 0; i < n; i++) {
