// Test checkout with unknown ISBN
try {
  library.checkout("unknown-isbn", "Bob");
  console.assert(false, "Should have thrown an error for unknown ISBN");
} catch (e) {
  console.assert(e.message === "Unknown ISBN: unknown-isbn", "Should throw correct error for unknown ISBN");
}

// Test checkout when no copies available
library.checkout("978-0-123456-78-9", "Bob");
library.checkout("978-0-123456-78-9", "Charlie");
try {
  library.checkout("978-0-123456-78-9", "David");
  console.assert(false, "Should have thrown an error when no copies available");
