// Matrix class implementation

class Matrix {
  constructor(rows) {
    // Check if rows is an array
    if (!Array.isArray(rows)) {
      throw new Error("Rows must be an array");
    }
    
    // Check if there are no rows
    if (rows.length === 0) {
      throw new Error("Matrix must have at least one row");
    }
    
    // Check if all rows are arrays and have the same length
    const firstRowLength = rows[0].length;
    if (firstRowLength === 0) {
      throw new Error("Matrix must have at least one column");
    }
    
    for (let i = 0; i < rows.length; i++) {
      if (!Array.isArray(rows[i])) {
        throw new Error("Each row must be an array");
      }
      if (rows[i].length !== firstRowLength) {
        throw new Error("All rows must have the same length");
      }
      for (let j = 0; j < rows[i].length; j++) {
        if (typeof rows[i][j] !== 'number' || !isFinite(rows[i][j])) {
          throw new Error("All entries must be finite numbers");
        }
      }
    }
    
    this._rows = rows;
  }
  
  shape() {
    return [this._rows.length, this._rows[0].length];
  }
  
  get(r, c) {
    if (r < 0 || r >= this._rows.length || c < 0 || c >= this._rows[0].length) {
      throw new Error("Index out of bounds");
    }
    return this._rows[r][c];
  }
  
  toArray() {
    // Return a copy of the rows
    return this._rows.map(row => [...row]);
  }
  
  add(other) {
    // Check if other is a Matrix
    if (!(other instanceof Matrix)) {
      throw new Error("Operand must be a Matrix");
    }
    
    // Check if shapes match
    const shape1 = this.shape();
    const shape2 = other.shape();
    if (shape1[0] !== shape2[0] || shape1[1] !== shape2[1]) {
      throw new Error("Matrix shapes must match for addition");
    }
    
    // Perform addition
    const resultRows = [];
    for (let i = 0; i < shape1[0]; i++) {
      const row = [];
      for (let j = 0; j < shape1[1]; j++) {
        row.push(this.get(i, j) + other.get(i, j));
      }
      resultRows.push(row);
    }
    
    return new Matrix(resultRows);
  }
  
  sub(other) {
    // Check if other is a Matrix
    if (!(other instanceof Matrix)) {
      throw new Error("Operand must be a Matrix");
    }
    
    // Check if shapes match
    const shape1 = this.shape();
    const shape2 = other.shape();
    if (shape1[0] !== shape2[0] || shape1[1] !== shape2[1]) {
      throw new Error("Matrix shapes must match for subtraction");
    }
    
    // Perform subtraction
    const resultRows = [];
    for (let i = 0; i < shape1[0]; i++) {
      const row = [];
      for (let j = 0; j < shape1[1]; j++) {
        row.push(this.get(i, j) - other.get(i, j));
      }
      resultRows.push(row);
    }
    
    return new Matrix(resultRows);
  }
  
  transpose() {
    const rows = this.shape()[0];
    const cols = this.shape()[1];
    const transposedRows = [];
    
    for (let j = 0; j < cols; j++) {
      const row = [];
      for (let i = 0; i < rows; i++) {
        row.push(this.get(i, j));
      }
      transposedRows.push(row);
    }
    
    return new Matrix(transposedRows);
  }
  
  static identity(n) {
    if (typeof n !== 'number' || n <= 0 || !Number.isInteger(n)) {
      throw new Error("n must be a positive integer");
    }
    
    const rows = [];
    for (let i = 0; i < n; i++) {
      const row = [];
      for (let j = 0; j < n; j++) {
        row.push(i === j ? 1 : 0);
      }
      rows.push(row);
    }
    
    return new Matrix(rows);
  }
}

// Asserts that all pass
function runAsserts() {
  // Test valid matrix
  const validMatrix = new Matrix([[1, 2, 3], [4, 5, 6]]);
  console.assert(validMatrix.shape()[0] === 2, "Shape rows should be 2");
  console.assert(validMatrix.shape()[1] === 3, "Shape cols should be 3");
  console.assert(validMatrix.get(0, 1) === 2, "get(0,1) should return 2");
  console.assert(validMatrix.get(1, 2) === 6, "get(1,2) should return 6");
  
  const arrayCopy = validMatrix.toArray();
  console.assert(arrayCopy[0][0] === 1, "toArray should return a copy");
  console.assert(arrayCopy[0][1] === 2, "toArray should return a copy");
  
  // Test error cases
  try {
    new Matrix([]);
    console.assert(false, "Should have thrown error for empty rows");
  } catch (e) {
    console.assert(e.message === "Matrix must have at least one row", "Should throw correct error for empty rows");
  }
  
  try {
    new Matrix([[]]);
    console.assert(false, "Should have thrown error for empty rows");
  } catch (e) {
    console.assert(e.message === "Matrix must have at least one column", "Should throw correct error for empty rows");
  }
  
  try {
    new Matrix([[1, 2], [3, 4, 5]]);
    console.assert(false, "Should have thrown error for different row lengths");
  } catch (e) {
    console.assert(e.message === "All rows must have the same length", "Should throw correct error for different row lengths");
  }
  
  try {
    new Matrix([[1, 2], [3, "invalid"]]);
    console.assert(false, "Should have thrown error for non-finite number");
  } catch (e) {
    console.assert(e.message === "All entries must be finite numbers", "Should throw correct error for non-finite number");
  }
  
  try {
    validMatrix.get(5, 0);
    console.assert(false, "Should have thrown error for out of bounds");
  } catch (e) {
    console.assert(e.message === "Index out of bounds", "Should throw correct error for out of bounds");
  }
  
  console.log("All asserts passed!");
}

// Test add and sub methods
function testAddSub() {
  // Test valid addition
  const m1 = new Matrix([[1, 2], [3, 4]]);
  const m2 = new Matrix([[5, 6], [7, 8]]);
  const sum = m1.add(m2);
  console.assert(sum.get(0, 0) === 6, "Addition failed");
  console.assert(sum.get(0, 1) === 8, "Addition failed");
  console.assert(sum.get(1, 0) === 10, "Addition failed");
  console.assert(sum.get(1, 1) === 12, "Addition failed");
  
  // Test valid subtraction
  const diff = m2.sub(m1);
  console.assert(diff.get(0, 0) === 4, "Subtraction failed");
  console.assert(diff.get(0, 1) === 4, "Subtraction failed");
  console.assert(diff.get(1, 0) === 4, "Subtraction failed");
  console.assert(diff.get(1, 1) === 4, "Subtraction failed");
  
  // Test that original matrices are unchanged
  console.assert(m1.get(0, 0) === 1, "Original matrix changed during addition");
  console.assert(m2.get(0, 0) === 5, "Original matrix changed during subtraction");
  
  // Test shape mismatch error for addition
  const m3 = new Matrix([[1, 2, 3], [4, 5, 6]]);
  try {
    m1.add(m3);
    console.assert(false, "Should have thrown error for shape mismatch in addition");
  } catch (e) {
    console.assert(e.message === "Matrix shapes must match for addition", "Should throw correct error for addition shape mismatch");
  }
  
  // Test shape mismatch error for subtraction
  try {
    m1.sub(m3);
    console.assert(false, "Should have thrown error for shape mismatch in subtraction");
  } catch (e) {
    console.assert(e.message === "Matrix shapes must match for subtraction", "Should throw correct error for subtraction shape mismatch");
  }
  
  // Test non-Matrix operand error
  try {
    m1.add("not a matrix");
    console.assert(false, "Should have thrown error for non-Matrix operand in addition");
  } catch (e) {
    console.assert(e.message === "Operand must be a Matrix", "Should throw correct error for non-Matrix operand in addition");
  }
  
  try {
    m1.sub("not a matrix");
    console.assert(false, "Should have thrown error for non-Matrix operand in subtraction");
  } catch (e) {
    console.assert(e.message === "Operand must be a Matrix", "Should throw correct error for non-Matrix operand in subtraction");
  }
  
  console.log("Add and sub tests passed!");
}

// Add transpose method
Matrix.prototype.transpose = function() {
  const transposedRows = [];
  for (let i = 0; i < this.rows[0].length; i++) {
    const row = [];
    for (let j = 0; j < this.rows.length; j++) {
      row.push(this.rows[j][i]);
    }
    transposedRows.push(row);
  }
  return new Matrix(transposedRows);
};

// Add identity static method
Matrix.identity = function(n) {
  if (typeof n !== 'number' || n <= 0 || !Number.isInteger(n)) {
    throw new Error("n must be a positive integer");
  }
  
  const rows = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      row.push(i === j ? 1 : 0);
    }
    rows.push(row);
  }
  return new Matrix(rows);
};

testAddSub();
runAsserts();

// Export the Matrix class
module.exports = { Matrix };

