                result += parseTerm();
            } else if (char === '-') {
                pos++;
                result -= parseTerm();
            } else {
                break;
            }
        }

        return result;
    }

    function parsePower() {
        let result = parseFactor();

        // Handle right-associative power operations
        if (expr[pos] === '^') {
            pos++;
            const exponent = parsePower();  // Right-associative: 2^3^2 = 2^(3^2) = 2^9 = 512
            result = Math.pow(result, exponent);
        }

        return result;
    }

    function parseTerm() {
        let result = parsePower();

        while (true) {
            const char = expr[pos];
            if (char === '*') {
                pos++;
                result *= parsePower();
            } else if (char === '/') {
                pos++;
                const divisor = parsePower();
