const { Library } = require('./s1_library.js');
const { Cache } = require('./s7_cache.js');

function shelfLine(library) {
  const titles = library.titles();
  if (titles.length === 0) {
    return '(empty)';
  }
  return titles.join(', ');
}

function availability(library, isbn) {
  const available = library.available(isbn);
  const copies = library.copies(isbn);
  return `${available}/${copies}`;
}

function memberLine(library, member) {
  const loans = library.getLoans(member);
  if (loans.length === 0) {
    return `${member}: none`;
  }
  return `${member}: ${loans.join(', ')}`;
}

function makeLookup(library, cache) {
  return function(isbn) {
    if (cache.has(isbn)) {
      return cache.get(isbn);
    }
    const result = availability(library, isbn);
    cache.set(isbn, result);
    return result;
  };
}

function overdueLines(library, today) {
  const overdue = library.overdue(today);
  if (overdue.length === 0) {
    return '';
  }
  return overdue.map(item => `${item.member} owes ${item.isbn} (${item.daysLate} days)`).join('\n');
}

// Export the functions
module.exports = { shelfLine, availability, memberLine, makeLookup, overdueLines };

// Test asserts
const testLibrary = new Library();

// Test with empty library
console.assert(shelfLine(testLibrary) === '(empty)', 'Should return "(empty)" for empty library');

// Test with one book
testLibrary.addBook("978-0-123456-78-9", "The Great Gatsby", 3);
console.assert(shelfLine(testLibrary) === 'The Great Gatsby', 'Should return single title');

// Test with multiple books
testLibrary.addBook("978-0-987654-32-1", "1984");
testLibrary.addBook("978-0-111111-11-1", "Animal Farm", 1);
const result = shelfLine(testLibrary);
const expected = '1984, Animal Farm, The Great Gatsby';
console.assert(result === expected, `Should return sorted titles: ${expected}`);

console.log("All asserts passed!");

start.s1_library.js:
class Library {
  constructor() {
    this.books = new Map();
    this.loans = new Map(); // Track which members have which books
    this.holds = new Map(); // Track holds: isbn -> array of members waiting
    this.dueDates = new Map(); // Track due dates: member -> isbn -> dueDay
    this._fines = new Map(); // Track unpaid fines: member -> cents
  }
  
  addBook(isbn, title, copies = 1) {
    // Validate copies parameter
    if (!Number.isInteger(copies) || copies <= 0) {
      throw new Error("copies must be a positive integer");
    }
    
    if (this.books.has(isbn)) {
      // If ISBN already exists, add to existing copies
      const existingBook = this.books.get(isbn);
      existingBook.copies += copies;
    } else {
      // Add new book
      this.books.set(isbn, { title, copies });
    }
  }
  
  copies(isbn) {
    const book = this.books.get(isbn);
    return book ? book.copies : 0;
  }
  
  checkout(isbn, member, day = 0) {
    // Check if ISBN exists
    if (!this.books.has(isbn)) {
      throw new Error(`Unknown ISBN: ${isbn}`);
    }
    
    const book = this.books.get(isbn);
    
    // Check if any copies are available (total available minus what member already has)
    const totalAvailable = this.available(isbn);
    if (totalAvailable <= 0) {
      throw new Error(`No copies available for ISBN: ${isbn}`);
    }
    
    // Record the loan
    if (!this.loans.has(member)) {
      this.loans.set(member, new Map());
    }
    const memberLoans = this.loans.get(member);
    if (!memberLoans.has(isbn)) {
      memberLoans.set(isbn, 0);
    }
    memberLoans.set(isbn, memberLoans.get(isbn) + 1);
    
    // Set due date (14 days from checkout day)
    if (!this.dueDates.has(member)) {
      this.dueDates.set(member, new Map());
    }
    const memberDueDates = this.dueDates.get(member);
    memberDueDates.set(isbn, day + 14);
  }
  
  available(isbn) {
    const book = this.books.get(isbn);
    if (!book) {
      return 0;
    }
    
    // Calculate available copies as total copies minus copies currently on loan
    let totalLoans = 0;
    for (const memberLoans of this.loans.values()) {
      if (memberLoans.has(isbn)) {
        totalLoans += memberLoans.get(isbn);
      }
    }
    
    return book.copies - totalLoans;
  }
  
  _getMemberLoans(member, isbn) {
    if (!this.loans.has(member)) {
      return 0;
    }
    const memberLoans = this.loans.get(member);
    return memberLoans.has(isbn) ? memberLoans.get(isbn) : 0;
  }
  
  _memberHasBook(member, isbn) {
    return this._getMemberLoans(member, isbn) > 0;
  }
  
  placeHold(isbn, member) {
    // Check if ISBN exists
    if (!this.books.has(isbn)) {
      throw new Error(`Unknown ISBN: ${isbn}`);
    }
    
    // Check if any copies are available
    if (this.available(isbn) > 0) {
      throw new Error(`Book with ISBN ${isbn} is available, cannot place hold`);
    }
    
    // Check if member already has this book
    if (this._memberHasBook(member, isbn)) {
      throw new Error(`Member ${member} already has book with ISBN: ${isbn}`);
    }
    
    // Check if member already has a hold on this book
    if (this.holds.has(isbn)) {
      const holdQueue = this.holds.get(isbn);
      if (holdQueue.includes(member)) {
        throw new Error(`Member ${member} already has a hold on book with ISBN: ${isbn}`);
      }
    }
    
    // Add member to hold queue
    if (!this.holds.has(isbn)) {
      this.holds.set(isbn, []);
    }
    this.holds.get(isbn).push(member);
  }
  
  returnBook(isbn, member, day = 0) {
    // Check if member has this book
    if (!this._memberHasBook(member, isbn)) {
      throw new Error(`Member ${member} does not have book with ISBN: ${isbn}`);
    }
    
    // Calculate fine
    let fine = 0;
    if (this.dueDates.has(member)) {
      const memberDueDates = this.dueDates.get(member);
      if (memberDueDates.has(isbn)) {
        const dueDay = memberDueDates.get(isbn);
        const daysLate = Math.max(0, day - dueDay);
        fine = daysLate * 25; // 25 cents per day late
        
        // Add fine to member's unpaid fines
        if (!this._fines.has(member)) {
          this._fines.set(member, 0);
        }
        this._fines.set(member, this._fines.get(member) + fine);
      }
    }
    
    // Remove the loan
    const memberLoans = this.loans.get(member);
    memberLoans.set(isbn, memberLoans.get(isbn) - 1);
    
    // If no more copies of this book are loaned by this member, remove the entry
    if (memberLoans.get(isbn) === 0) {
      memberLoans.delete(isbn);
    }
    
    // If member has no more loans, remove the member entry
    if (memberLoans.size === 0) {
      this.loans.delete(member);
    }
    
    // Remove due date
    if (this.dueDates.has(member)) {
      const memberDueDates = this.dueDates.get(member);
      memberDueDates.delete(isbn);
      if (memberDueDates.size === 0) {
        this.dueDates.delete(member);
      }
    }
    
    // Check if there are any holds for this book
    if (this.holds.has(isbn) && this.holds.get(isbn).length > 0) {
      // Assign the book to the first member in the hold queue
      const firstHolder = this.holds.get(isbn).shift();
      this.checkout(isbn, firstHolder, day);
  }
  
  // Return the fine in cents
  return fine;
}

  fines(member) {
    // Return total unpaid fines for a member
    return this._fines.has(member) ? this._fines.get(member) : 0;
  }
  
  pay(member, cents) {
    // Validate payment amount
    if (typeof cents !== 'number' || cents <= 0 || !Number.isInteger(cents)) {
      throw new Error("Payment amount must be a positive integer");
    }
    
    // Check if member has fines
    if (!this.fines.has(member)) {
      throw new Error("No fines to pay");
    }
    
    const totalFines = this.fines.get(member);
    
    // Check if payment amount exceeds total fines
    if (cents > totalFines) {
      throw new Error("Payment amount exceeds total fines");
    }
    
    // Process payment
    if (cents === totalFines) {
      // Full payment - remove member from fines map
      this.fines.delete(member);
    } else {
      // Partial payment - reduce the fine amount
      this.fines.set(member, totalFines - cents);
    }
  }
  
  holds(isbn) {
    if (!this.holds.has(isbn)) {
      return [];
    }
    return [...this.holds.get(isbn)]; // Return a copy of the array
  }
  
  getLoans(member) {
    // Return sorted ISBNs that member has on loan
    if (!this.loans.has(member)) {
      return [];
    }
    const memberLoans = this.loans.get(member);
    return Array.from(memberLoans.keys()).sort();
  }
  
  dueDay(isbn, member) {
    if (!this.dueDates.has(member)) {
      return null;
    }
    const memberDueDates = this.dueDates.get(member);
    if (!memberDueDates.has(isbn)) {
      return null;
    }
    return memberDueDates.get(isbn);
  }
  
  titles() {
    const titles = [];
    for (const book of this.books.values()) {
      titles.push(book.title);
    }
    return titles.sort();
  }
  
  overdue(today) {
    const result = [];
    
    // Iterate through all due dates
    for (const [member, memberDueDates] of this.dueDates.entries()) {
      for (const [isbn, dueDay] of memberDueDates.entries()) {
        const daysLate = today - dueDay;
        if (daysLate > 0) {
          result.push({ isbn, member, daysLate });
        }
      }
    }
    
    // Sort by daysLate (largest first), then isbn, then member
    result.sort((a, b) => {
      if (b.daysLate !== a.daysLate) {
        return b.daysLate - a.daysLate;
      }
      if (a.isbn !== b.isbn) {
        return a.isbn.localeCompare(b.isbn);
      }
      return a.member.localeCompare(b.member);
    });
    
    return result;
  }
}

