        console.assert(false, 'Should have thrown an error');
    } catch (e) {
        console.assert(e.message.includes('at '), 'Error should contain position');
        console.log('Test 5 passed:', e.message);
    }
    
    try {
        evaluate('unknown_func()');
        console.assert(false, 'Should have thrown an error');
    } catch (e) {
