  console.assert(sum.get(1, 1) === 12, "Addition should work");
  
  const diff = matrix1.sub(matrix2);
  console.assert(diff.get(0, 0) === -4, "Subtraction should work");
  console.assert(diff.get(1, 1) === -4, "Subtraction should work");
  
  // Test transpose
