console.log('Testing tokenize function...');

// Test 1: Simple number
try {
    const tokens1 = tokenize('42');
    console.log('Test 1 - Simple number:', JSON.stringify(tokens1));
    console.assert(tokens1.length === 1 && tokens1[0].type === 'num' && tokens1[0].value === 42);
    console.log('Test 1 passed');
} catch (e) {
    console.error('Test 1 failed:', e.message);
}

// Test 2: Simple expression
try {
    const tokens2 = tokenize('1 + 2');
    console.log('Test 2 - Simple expression:', JSON.stringify(tokens2));
    console.assert(tokens2.length === 3);
    console.assert(tokens2[0].type === 'num' && tokens2[0].value === 1);
    console.assert(tokens2[1].type === 'op' && tokens2[1].value === '+');
    console.assert(tokens2[2].type === 'num' && tokens2[2].value === 2);
    console.log('Test 2 passed');
} catch (e) {
    console.error('Test 2 failed:', e.message);
}

// Test 3: Variable name
try {
    const tokens3 = tokenize('x');
    console.log('Test 3 - Variable name:', JSON.stringify(tokens3));
    console.assert(tokens3.length === 1 && tokens3[0].type === 'name' && tokens3[0].value === 'x');
    console.log('Test 3 passed');
} catch (e) {
    console.error('Test 3 failed:', e.message);
}

// Test 4: Function call
try {
    const tokens4 = tokenize('abs(-5)');
    console.log('Test 4 - Function call:', JSON.stringify(tokens4));
    console.assert(tokens4.length === 4);
    console.assert(tokens4[0].type === 'name' && tokens4[0].value === 'abs');
    console.assert(tokens4[1].type === 'lparen');
    console.assert(tokens4[2].type === 'op' && tokens4[2].value === '-');
