const { evaluate, tokenize } = require('./s5_expr.js');

// Test tokenize function
console.log('Testing tokenize function...');

// Test 1: Simple number
try {
    const tokens1 = tokenize('42');
    console.log('Test 1 - Simple number:', JSON.stringify(tokens1));
    console.assert(tokens1.length === 1 && tokens1[0].type === 'num' && tokens1[0].value === 42);
    console.log('Test 1 passed');
} catch (e) {
    console.error('Test 1 failed:', e.message);
}

// Test 2: Simple expression
try {
    const tokens2 = tokenize('1 + 2');
    console.log('Test 2 - Simple expression:', JSON.stringify(tokens2));
    console.assert(tokens2.length === 3);
    console.assert(tokens2[0].type === 'num' && tokens2[0].value === 1);
    console.assert(tokens2[1].type === 'op' && tokens2[1].value === '+');
    console.assert(tokens2[2].type === 'num' && tokens2[2].value === 2);
    console.log('Test 2 passed');
} catch (e) {
    console.error('Test 2 failed:', e.message);
}

// Test 3: Variable name
try {
    const tokens3 = tokenize('x');
    console.log('Test 3 - Variable name:', JSON.stringify(tokens3));
    console.assert(tokens3.length === 1 && tokens3[0].type === 'name' && tokens3[0].value === 'x');
    console.log('Test 3 passed');
} catch (e) {
    console.error('Test 3 failed:', e.message);
}

// Test 4: Function call
try {
    const tokens4 = tokenize('abs(-5)');
    console.log('Test 4 - Function call:', JSON.stringify(tokens4));
    console.assert(tokens4.length === 4);
    console.assert(tokens4[0].type === 'name' && tokens4[0].value === 'abs');
    console.assert(tokens4[1].type === 'lparen');
    console.assert(tokens4[2].type === 'op' && tokens4[2].value === '-');
    console.assert(tokens4[3].type === 'num' && tokens4[3].value === 5);
    console.log('Test 4 passed');
} catch (e) {
    console.error('Test 4 failed:', e.message);
}

// Test 5: Complex expression
try {
    const tokens5 = tokenize('2 * (3 + 4) / 5');
    console.log('Test 5 - Complex expression:', JSON.stringify(tokens5));
    console.assert(tokens5.length === 7);
    console.assert(tokens5[0].type === 'num' && tokens5[0].value === 2);
    console.assert(tokens5[1].type === 'op' && tokens5[1].value === '*');
    console.assert(tokens5[2].type === 'lparen');
    console.assert(tokens5[3].type === 'num' && tokens5[3].value === 3);
    console.assert(tokens5[4].type === 'op' && tokens5[4].value === '+');
    console.assert(tokens5[5].type === 'num' && tokens5[5].value === 4);
    console.assert(tokens5[6].type === 'rparen');
    console.log('Test 5 passed');
} catch (e) {
    console.error('Test 5 failed:', e.message);
}

// Test 6: Decimal number
try {
    const tokens6 = tokenize('3.14');
    console.log('Test 6 - Decimal number:', JSON.stringify(tokens6));
    console.assert(tokens6.length === 1 && tokens6[0].type === 'num' && tokens6[0].value === 3.14);
    console.log('Test 6 passed');
} catch (e) {
    console.error('Test 6 failed:', e.message);
}

// Test 7: Invalid character
try {
    tokenize('1 @ 2');
    console.error('Test 7 failed: Should have thrown an error');
} catch (e) {
    console.log('Test 7 - Invalid character:', e.message);
    console.assert(e.message.includes('Invalid characters'));
    console.log('Test 7 passed');
}

// Test 8: Empty expression
try {
    tokenize('');
    console.error('Test 8 failed: Should have thrown an error');
} catch (e) {
    console.log('Test 8 - Empty expression:', e.message);
    console.assert(e.message.includes('Empty expression'));
    console.log('Test 8 passed');
}

console.log('All tokenize tests completed.');

