      return a.member.localeCompare(b.member);
    });

    // Serialize holds - only books that have holds
    const holds = {};
    for (const [isbn, members] of this.holds.entries()) {
      if (members.length > 0) {
        holds[isbn] = [...members]; // Return a copy of the array
      }
    }

