    console.log('FAIL: Recently used item should still be accessible');
    return false;
  }
  
  if (cache.get('d') !== 4) {
    console.log('FAIL: Recently added item should be accessible');
    return false;
  }
  
  console.log('All tests passed!');
  return true;
