const { Cache } = require('./s7_cache.js');

// Test the resize functionality
console.log('Testing resize functionality...');

// Create a cache with capacity 3
const cache = new Cache(3);

// Add some items
cache.set('a', 1);
cache.set('b', 2);
cache.set('c', 3);
console.log('Added items a, b, c');

