// Cache class implementation
class Cache {
  constructor(capacity, options = {}) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error('Capacity must be a positive integer');
    }
    this.capacity = capacity;
    this.map = new Map();
    this.ttl = options.ttl || null;
    this.now = options.now || (() => Date.now());
    this.onEvict = options.onEvict || null;
    // Stats tracking
    this.hits = 0;
    this.misses = 0;
    this.evictions = 0;
    this.expirations = 0;
  }
  
  set(key, value, options = {}) {
    if (this.map.has(key)) {
      // Update existing key
      this.map.delete(key);
    } else if (this.map.size >= this.capacity) {
      // Remove least recently used item
      const firstKey = this.map.keys().next().value;
      const entry = this.map.get(firstKey);
      this.map.delete(firstKey);
      if (this.onEvict) {
        this.onEvict(firstKey, entry.value, 'lru');
      }
    }
    
    const ttl = options.ttl !== undefined ? options.ttl : this.ttl;
    const expiry = ttl !== null ? this.now() + ttl : null;
    
    this.map.set(key, { value, expiry });
  }
  
  get(key) {
    if (!this.map.has(key)) {
      this.misses++;
      return undefined;
    }
    // Check if entry has expired
    const entry = this.map.get(key);
    if (entry.expiry !== null && this.now() > entry.expiry) {
      this.map.delete(key);
      this.expirations++;
      if (this.onEvict) {
        this.onEvict(key, entry.value, 'expired');
      }
      return undefined;
    }
    // Move to end to mark as recently used
    const value = entry.value;
    this.map.delete(key);
    this.map.set(key, entry);
    this.hits++;
    return value;
  }
  
  peek(key) {
    if (!this.map.has(key)) {
      return undefined;
    }
    // Check if entry has expired
    const entry = this.map.get(key);
    if (entry.expiry !== null && this.now() > entry.expiry) {
      this.map.delete(key);
      return undefined;
    }
    // Just return the value without marking as recently used
    return entry.value;
  }
  
  has(key) {
    if (!this.map.has(key)) {
      return false;
    }
    // Check if entry has expired
    const entry = this.map.get(key);
    if (entry.expiry !== null && this.now() > entry.expiry) {
      this.map.delete(key);
      return false;
    }
    return true;
  }
  
  size() {
    let count = 0;
    for (const entry of this.map.values()) {
      if (entry.expiry === null || this.now() <= entry.expiry) {
        count++;
      }
    }
    return count;
  }
  
  delete(key) {
    const entry = this.map.get(key);
    const deleted = this.map.delete(key);
    if (deleted && this.onEvict) {
      this.onEvict(key, entry.value, 'deleted');
    }
    return deleted;
  }
  
  clear() {
    if (this.onEvict) {
      for (const [key, entry] of this.map.entries()) {
        this.onEvict(key, entry.value, 'deleted');
      }
    }
    this.map.clear();
  }
  
  keys() {
    return Array.from(this.map.keys());
  }
  
  stats() {
    return {
      hits: this.hits,
      misses: this.misses,
      evictions: this.evictions,
      expirations: this.expirations
    };
  }

  resize(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error('Capacity must be a positive integer');
    }
    
    // Evict LRU entries until we're under the new capacity
    while (this.map.size > capacity) {
      // Get the first key (LRU entry)
      const firstKey = this.map.keys().next().value;
      const entry = this.map.get(firstKey);
      this.map.delete(firstKey);
      if (this.onEvict) {
        this.onEvict(firstKey, entry.value, 'lru');
      }
      this.evictions++;
    }
    
    this.capacity = capacity;
  }
}

