const { Cache } = require('./s7_cache.js');

function shelfLine(library) {
  const titles = library.titles();
  if (titles.length === 0) {
    return '(empty)';
  }
  return titles.join(', ');
}

function availability(library, isbn) {
  const available = library.available(isbn);
  const copies = library.copies(isbn);
  return `${available}/${copies}`;
}

function memberLine(library, member) {
  const loans = library.getLoans(member);
  if (loans.length === 0) {
    return `${member}: none`;
  }
  return `${member}: ${loans.join(', ')}`;
}

function makeLookup(library, cache) {
  return function(isbn) {
    if (cache.has(isbn)) {
      return cache.get(isbn);
    }
    const result = availability(library, isbn);
    cache.set(isbn, result);
    return result;
  };
}

function overdueLines(library, today) {
  const overdue = library.overdue(today);
  if (overdue.length === 0) {
    return '';
  }
  return overdue.map(item => `${item.member} owes ${item.isbn} (${item.daysLate} days)`).join('\n');
}

// Export the functions
module.exports = { shelfLine, availability, memberLine, makeLookup, overdueLines, canBorrow };

// Test asserts
const testLibrary = new Library();

// Test with empty library
console.assert(shelfLine(testLibrary) === '(empty)', 'Should return "(empty)" for empty library');

// Test with one book
testLibrary.addBook("978-0-123456-78-9", "The Great Gatsby", 3);
console.assert(shelfLine(testLibrary) === 'The Great Gatsby', 'Should return single title');

// Test with multiple books
testLibrary.addBook("978-0-987654-32-1", "1984");
testLibrary.addBook("978-0-111111-11-1", "Animal Farm", 1);
const result = shelfLine(testLibrary);
const expected = '1984, Animal Farm, The Great Gatsby';
console.assert(result === expected, `Should return sorted titles: ${expected}`);

console.log("All asserts passed!");
function fineReport(library, members) {
  // Get all loans with fines for the given members
  const fines = [];
  
  for (const member of members) {
    const loans = library.getLoans(member);
    for (const loan of loans) {
      const fine = library.getFine(loan, member);
      if (fine > 0) {
        fines.push({ member, fine });
      }
    }
  }
  
  // Sort by fine amount (descending) then by member name (ascending)
  fines.sort((a, b) => {
    if (b.fine !== a.fine) {
      return b.fine - a.fine; // Descending by fine amount
    }
    return a.member.localeCompare(b.member); // Ascending by member name
  });
  
  // Format the output
  return fines.map(item => `member: ${item.fine.toFixed(2)}`).join('\n');
}

function canBorrow(library, member) {
  const loans = library.getLoans(member);
  const fines = library.getFine(member);
  
  return loans.length < 3 && fines < 500;
}

// Export the functions
module.exports = { shelfLine, availability, memberLine, makeLookup, overdueLines, fineReport, canBorrow };
// Add snapshot and restore functions
function snapshot(library, cache, key) {
  const data = JSON.stringify(library.toJSON());
  cache.set(key, data);
  return data;
}

function restore(cache, key) {
  const data = cache.get(key);
  if (data === undefined) {
    return null;
  }
  return Library.fromJSON(JSON.parse(data));
}

