    // Create cofactor matrix
    const cofactorRows = [];
    for (let i = 0; i < rows; i++) {
      const cofactorRow = [];
      for (let j = 0; j < cols; j++) {
        // Create minor matrix by removing row i and column j
        const minorRows = [];
        for (let k = 0; k < rows; k++) {
          if (k !== i) {
