    const books = [];
    for (const [isbn, book] of this.books.entries()) {
      books.push({ isbn, title: book.title, copies: book.copies });
    }
    books.sort((a, b) => a.isbn.localeCompare(b.isbn));

    // Serialize loans sorted by isbn then member
