      throw new Error(`Cannot remove book with ISBN ${isbn}: book has holds`);
    }
    
    // Remove the book
    this.books.delete(isbn);
    
    // Remove any holds for this book (if any)
    if (this.holds.has(isbn)) {
      this.holds.delete(isbn);
    }
    
    return true;
  }
}
